	MOVD ctx+0(FP), R0

	// Preload values
	MOVBU 8(R0), R2
	MOVD  32(R0), R3
	MOVD  16(R0), R5
	MOVD  24(R0), R6
	ADD   R5, R6, R6
	MOVD  56(R0), R7
	MOVD  48(R0), R8
	MOVD  (R0), R1
	MOVD  32(R1), R9
	MOVBU 40(R1), R10

outer_loop:
	// Iterations allowed by the output: (limit - op) / 8
	MOVD R6, R1
	SUBS R5, R1, R1
	BLE  done
	LSR  $0x03, R1, R1

	// Iterations allowed by the input: a refill reads the 8 bytes below the window and
	// moves it down by at most 7, so every read stays inside the stream while ip stays
	// at least 8 above ilowest.
	MOVD    R7, R11
	SUB     R8, R11, R11
	LSR     $0x03, R11, R11
	CMP     R1, R11
	CSEL    LO, R11, R1, R1
	TST     R1, R1
	BEQ     done
	MOVD    $7, R16
	MUL     R16, R1, R11
	ADD     R5, R11, R11
	PCALIGN $0x40

inner_loop:
	// symbol 0
	LSR   R2, R9, R12
	MOVHU (R3)(R12<<1), R1
	LSL   R1, R9, R9
	ADD   R1, R10, R10
	LSR   $0x08, R1, R1
	MOVB  R1, (R5)

	// symbol 1
	LSR   R2, R9, R12
	MOVHU (R3)(R12<<1), R1
	LSL   R1, R9, R9
	ADD   R1, R10, R10
	LSR   $0x08, R1, R1
	MOVB  R1, 1(R5)

	// symbol 2
	LSR   R2, R9, R12
	MOVHU (R3)(R12<<1), R1
	LSL   R1, R9, R9
	ADD   R1, R10, R10
	LSR   $0x08, R1, R1
	MOVB  R1, 2(R5)

	// symbol 3
	LSR   R2, R9, R12
	MOVHU (R3)(R12<<1), R1
	LSL   R1, R9, R9
	ADD   R1, R10, R10
	LSR   $0x08, R1, R1
	MOVB  R1, 3(R5)

	// symbol 4
	LSR   R2, R9, R12
	MOVHU (R3)(R12<<1), R1
	LSL   R1, R9, R9
	ADD   R1, R10, R10
	LSR   $0x08, R1, R1
	MOVB  R1, 4(R5)

	// symbol 5
	LSR   R2, R9, R12
	MOVHU (R3)(R12<<1), R1
	LSL   R1, R9, R9
	ADD   R1, R10, R10
	LSR   $0x08, R1, R1
	MOVB  R1, 5(R5)

	// symbol 6
	LSR   R2, R9, R12
	MOVHU (R3)(R12<<1), R1
	LSL   R1, R9, R9
	ADD   R1, R10, R10
	LSR   $0x08, R1, R1
	MOVB  R1, 6(R5)

	// Refill the whole bytes consumed from below the window
	MOVD R10, R12
	AND  $0x38, R12, R12
	MOVD -8(R7), R13
	LSR  $0x01, R13, R13
	AND  $0x07, R10, R10
	MOVD R12, R1
	EOR  $0x3f, R1, R1
	LSR  R1, R13, R13
	MOVD R10, R1
	LSL  R1, R13, R13
	ORR  R13, R9, R9
	LSR  $0x03, R12, R12
	SUB  R12, R7, R7
	ADD  $0x07, R5, R5
	CMP  R11, R5
	BLO  inner_loop
	JMP  outer_loop

done:
	// Hand the state back in the Go bit reader's own form: off = ip - in, value, bitsRead.
	MOVD (R0), R1
	MOVD (R1), R16
	SUB  R16, R7, R7
	MOVD R7, 24(R1)
	MOVD R9, 32(R1)
	MOVB R10, 40(R1)
	MOVD 16(R0), R16
	SUB  R16, R5, R5
	MOVD R5, 40(R0)
	RET

